LINES = [{'id': 'rule', 'text': 'In this town, the more people ignore you, the smaller you get. Just ask my dad.'}, {'id': 'dinner', 'text': 'Dad told fourteen jokes at dinner. Zero laughs. By dessert, he was the size of the ketchup.'}, {'id': 'noticed', 'text': "But get noticed, and you grow. Preston from my school has two million followers. He's nine feet tall."}, {'id': 'mayor', 'text': 'The mayor gave a speech to an empty street. By the end, he was shorter than a hydrant.'}, {'id': 'mailman', 'text': "Careful, though. Our mailman got so tall nobody could see his face. People stopped looking up. Now he's mailbox-sized."}, {'id': 'leo', 'text': 'My little brother Leo is shy. This week he raised his hand forty times. Nobody called on him.'}, {'id': 'backpack', 'text': 'By Friday, Leo was so small he rode to school inside my backpack.'}, {'id': 'shrimp', 'text': "Preston laughed. Everybody, don't look at the shrimp. Nobody looks at shrimps. Trust me."}, {'id': 'show', 'text': 'Saturday was the town talent show. Preston went live, and the whole town watched only him.'}, {'id': 'everyone', 'text': 'But everyone staring at Preston meant nobody was looking at anyone else. So we all started shrinking.'}, {'id': 'kneehigh', 'text': 'In ten minutes, the whole town was knee-high. And Preston was so huge, all we could see were his shoes.'}, {'id': 'twist', 'text': 'Just like the mailman. Nobody could see his face, so nobody looked up. Preston started shrinking.'}, {'id': 'crying', 'text': 'Smaller than me. Smaller than a sneaker. Then the great Preston sat in the grass and cried.'}, {'id': 'brave', 'text': 'I was shrinking too. So I did something brave. I put my phone away and looked at Leo.'}, {'id': 'onelook', 'text': 'Just one person looking. Leo grew back to full size. He looked back at me, and I grew too.'}, {'id': 'kneel', 'text': 'Then Leo walked over to tiny Preston, knelt down, and looked right at him.'}, {'id': 'secret', 'text': 'Preston whispered, in first grade I was this small. Nobody looked at me for a whole year.'}, {'id': 'isee', 'text': 'Leo said, I see you. And Preston grew. Not giant. Just regular Preston size, for the first time in years.'}, {'id': 'town', 'text': 'Then the whole town looked at each other. Bo, Zoe, the mayor, even the mailman popped back up.'}, {'id': 'callback', 'text': "And Dad? Now we laugh at every single joke. He's eight feet tall. Nobody's told him they're terrible."}]
TITLES = [('@rule+0.4', '@rule+2.0', 'SHRINKING'), ('@noticed+0.4', '@noticed.end+0.3', 'FOLLOWERS'), ('@show+0.4', '@show.end+0.3', 'TALENT SHOW'), ('@twist+0.4', '@twist.end+0.3', 'UH OH'), ('@isee+0.4', '@isee.end+0.3', 'I SEE YOU'), ('@callback+0.4', '@callback.end+0.3', '8 FEET')]
